#!/usr/bin/env python3
import subprocess, base64, os, sys
os.chdir(os.path.expanduser("~/IVANNA-OMEGA-SUPREME"))
r = subprocess.run(["git","pull","--rebase","origin","main"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0: print("ERROR pull:", r.stderr); sys.exit(1)

data = base64.b64decode("")
os.makedirs("src/components", exist_ok=True)
with open("src/components/Iso226CalibrationPanel.tsx", "wb") as f: f.write(data)
print(f"Escrito: src/components/Iso226CalibrationPanel.tsx ({len(data)} bytes)")

r = subprocess.run(["git","add","src/components/Iso226CalibrationPanel.tsx"], capture_output=True, text=True)
if r.returncode != 0: print("ERROR add:", r.stderr); sys.exit(1)

r = subprocess.run(["git","status","--porcelain","src/components/Iso226CalibrationPanel.tsx"], capture_output=True, text=True)
if not r.stdout.strip(): print("Sin cambios — ya commitado"); sys.exit(0)

r = subprocess.run(["git","commit","-m","feat(ui): panel ISO 226 muestra estado real EQ+DSP+Socket por capa"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0: print("ERROR commit:", r.stderr); sys.exit(1)

r = subprocess.run(["git","push","origin","main"], capture_output=True, text=True)
print(r.stdout.strip(), r.stderr.strip())
if r.returncode != 0: print("ERROR push:", r.stderr); sys.exit(1)
print("OK: src/components/Iso226CalibrationPanel.tsx")
